//! Strategy registry.
//!
//! Adding or removing a strategy requires touching 4 places:
//! 1. `types.rs`: the variant in `StrategyId` + its arm in `Display` +
//!    its arm in `FromStr` + its entry in `ALL` (4 mechanical lines,
//!    protected by the compiler's exhaustive `match` -- deliberately not
//!    generated by a macro).
//! 2. This file: one entry in the `register_strategies!` table below.
//! 3. `strategy/mod.rs`: `pub mod xxx;` + `pub use xxx::Xxx;`.
//! 4. `strategy/supervisor.rs`: one arm in `universe()` and one in `build()`
//!    -- both exhaustive `match`es protected by the compiler (a missing arm
//!    does not compile), but NOT generated by this macro. This is a known,
//!    deliberate duplication, not an oversight: `build()` constructs the
//!    concrete instance for the manual hot-toggle (outside the initial
//!    spawn in `spawn_all`) and unifying it with the table below was left
//!    out of scope. Keep both `match`es in sync by hand when touching 2.
//!
//! `Follower` (does not implement `Strategy`, standalone task) is left out
//! of the table entirely -- its config remains a hand-written field in `Config`.
//! `PostCloseSweep` IS in the table (config/limits/requires_oracle
//! generated like the others) but is excluded from the automatic spawn
//! (`manual_spawn` in `spawn_all`) because it needs to extract
//! `taker_poller_handles()` from the instance before spawning it -- see
//! `main.rs`.

use std::sync::Arc;

use crate::{
    config::{Config, StrategyLimits},
    coordination::BracketLedger,
    market_feed::MarketRegistry,
    risk::RiskGuard,
    types::{BookSnapshot, Fill, QueuedIntent, StrategyId, VolSnapshot},
};

use super::{run, Strategy, StrategyCtx};

/// What each strategy constructor needs, besides its own config
/// (reachable via `ctx.config.strategies.<field>`). No constructor
/// receives more than it already received in `main.rs` before this
/// change -- this struct only groups what used to be passed loose.
pub struct BuildCtx {
    pub config: Arc<Config>,
    pub registry: Arc<MarketRegistry>,
    pub ledger: Arc<BracketLedger>,
    /// `broadcast::Sender<ModelPrediction>` wrapped in `Arc` so it can be
    /// cloned when passed to constructors (the `Receiver` derived from the
    /// tool is injected into `ModelBtc5m::new` as its own
    /// `broadcast::Receiver`). If the tool is not active (`None`), the
    /// constructors other than `ModelBtc5m` ignore it.
    pub model_prediction_tx: Option<Arc<tokio::sync::broadcast::Sender<crate::tools::model::ModelPrediction>>>,
    /// ARB-15M5M: TWAP strike store and destination of the per-streak telemetry.
    pub arb15m5m: crate::strategy::Arb15m5mDeps,
}

macro_rules! register_strategies {
    ( $( $variant:ident => $field:ident, $cfgty:ty, $requires_oracle:literal, $ctor:expr ),+ $(,)? ) => {
        /// Aggregated config of all registered strategies. Embedded in
        /// `Config` via `#[serde(flatten)]` -- each field is still a
        /// top-level TOML table (`[arb]`, `[near_certain]`, ...).
        #[derive(Debug, Clone, serde::Deserialize, Default)]
        pub struct StrategyConfigs {
            $( #[serde(default)] pub $field: $cfgty, )+
        }

        /// Replaces the old hand-written `Config::strategy_limits` match.
        /// `Follower` is not in the table -- it is resolved separately.
        pub fn strategy_limits(id: StrategyId, config: &Config) -> &StrategyLimits {
            match id {
                $( StrategyId::$variant => <$cfgty as crate::strategy::StrategyConfig>::limits(&config.strategies.$field), )+
                StrategyId::Follower => &config.follower.limits,
            }
        }

        /// Replaces the central `config::strategy_requires_oracle` table.
        pub fn strategy_requires_oracle(id: StrategyId) -> bool {
            match id {
                $( StrategyId::$variant => $requires_oracle, )+
                // Follower does not go through `strategy::run` (the only
                // real consumer of this value), so the result is
                // irrelevant in practice.
                StrategyId::Follower => false,
            }
        }

        /// All variants with an entry in this table (all of `StrategyId::ALL`
        /// except `Follower`, which is left out on purpose -- see the module
        /// doc comment).
        pub const REGISTERED: &[StrategyId] = &[ $( StrategyId::$variant ),+ ];

        /// Registers limits in `RiskGuard` (including the kill switch of the
        /// disabled ones). Must be called BEFORE spawning any task that may
        /// query `RiskGuard::get_strategy_limits` (executor, API,
        /// `settlement::orphan::run`) -- otherwise those tasks see the
        /// hardcoded defaults until `spawn_all` runs. Replaces the limits
        /// block (formerly a literal list of tuples) in `main.rs`.
        pub fn register_limits(config: &Config, risk: &Arc<RiskGuard>) {
            $(
                {
                    let lim = <$cfgty as crate::strategy::StrategyConfig>::limits(&config.strategies.$field);
                    risk.set_strategy_limits(
                        StrategyId::$variant,
                        lim.max_orders_per_hour,
                        lim.max_order_usdc,
                        lim.daily_loss_usdc_stop,
                    );
                    // Also kill the ones blocked by mode (not only
                    // `enabled=false`), so the `RiskGuard` state matches
                    // what `spawn_all` will do below.
                    if let Err(reason) = lim.can_run(config.mode) {
                        risk.kill_strategy(
                            StrategyId::$variant,
                            format!("at startup in mode {}: {reason}", config.mode),
                        );
                    }
                }
            )+
        }

        /// Spawns each enabled strategy, except those listed in
        /// `manual_spawn` (currently only `PostCloseSweep` -- see the module
        /// doc comment). Limit registration in `RiskGuard` does NOT happen
        /// here -- call `register_limits` first, see its doc comment.
        /// Replaces the `spawn_strategy!` macro (formerly repeated per
        /// strategy) in `main.rs`.
        #[allow(clippy::too_many_arguments)]
        pub fn spawn_all(
            ctx: &BuildCtx,
            risk: &Arc<RiskGuard>,
            tasks: &mut tokio::task::JoinSet<()>,
            task_names: &mut std::collections::HashMap<tokio::task::Id, String>,
            book_tx: &tokio::sync::broadcast::Sender<Arc<BookSnapshot>>,
            vol_rxs: &std::collections::HashMap<String, tokio::sync::watch::Receiver<VolSnapshot>>,
            intent_tx: &tokio::sync::mpsc::Sender<QueuedIntent>,
            fill_tx: &tokio::sync::broadcast::Sender<Fill>,
            kill_rx: &tokio::sync::watch::Receiver<bool>,
            max_book_age_ms: u64,
            manual_spawn: &[StrategyId],
        ) {
            $(
                {
                    let lim = <$cfgty as crate::strategy::StrategyConfig>::limits(&ctx.config.strategies.$field);
                    // In live `enabled` is not enough: `paper_only` blocks it.
                    // The `Disabled` case is not
                    // logged here: `register_limits` already emitted its
                    // `warn` (via `kill_strategy`) for each blocked
                    // strategy, and repeating a line per switched-off
                    // strategy on every startup would only bury the ones
                    // that matter.
                    let allowed = match lim.can_run(ctx.config.mode) {
                        Ok(()) => true,
                        Err(crate::config::BlockReason::Disabled) => false,
                        Err(reason) => {
                            tracing::warn!(
                                strategy = %StrategyId::$variant, mode = %ctx.config.mode,
                                "NOT started (enabled = true but the paper/live barrier blocks it): {reason}"
                            );
                            false
                        }
                    };
                    if allowed && !manual_spawn.contains(&StrategyId::$variant) {
                        let strategy_ctx = StrategyCtx {
                            book_rx:   book_tx.subscribe(),
                            vol_rxs:   vol_rxs.clone(),
                            intent_tx: intent_tx.clone(),
                            fill_rx:   fill_tx.subscribe(),
                            risk:      risk.clone(),
                            shutdown:  kill_rx.clone(),
                            max_book_age: std::time::Duration::from_millis(max_book_age_ms),
                            registry:  ctx.registry.clone(),
                            universe:  lim.universe.clone(),
                            requires_oracle: $requires_oracle,
                        };
                        let strategy: Box<dyn Strategy> = Box::new(($ctor)(ctx));
                        let h = tasks.spawn(run(strategy, strategy_ctx));
                        task_names.insert(h.id(), format!("strategy:{}", StrategyId::$variant));
                    }
                }
            )+
        }
    };
}

register_strategies! {
    Arb            => arb,             crate::strategy::arb::ArbConfig,     false, |ctx: &BuildCtx| crate::strategy::Arb::new(ctx.config.strategies.arb.clone()),
    Directional    => directional,     crate::strategy::directional::DirectionalConfig,    true,  |ctx: &BuildCtx| crate::strategy::Directional::new(ctx.config.strategies.directional.clone(), ctx.config.fair_value.confidence_haircut),
    NearCertain    => near_certain,    crate::strategy::near_certain::NearCertainConfig,    true,  |ctx: &BuildCtx| crate::strategy::NearCertain::new(ctx.config.strategies.near_certain.clone(), ctx.config.fair_value.confidence_haircut),
    NearExpiry     => near_expiry,     crate::strategy::near_expiry::NearExpiryConfig,     true,  |ctx: &BuildCtx| crate::strategy::NearExpiry::new(ctx.config.strategies.near_expiry.clone()),
    MarketMaking   => market_making,   crate::strategy::market_making::MarketMakingConfig,   true,  |ctx: &BuildCtx| crate::strategy::MarketMaking::new(ctx.config.strategies.market_making.clone()),
    ParityMaker    => parity_maker,    crate::strategy::parity_maker::ParityMakerConfig,    false, |ctx: &BuildCtx| crate::strategy::ParityMaker::new(ctx.config.strategies.parity_maker.clone()),
    DriftBox       => drift_box,       crate::strategy::drift_box::DriftBoxConfig,       true,  |ctx: &BuildCtx| crate::strategy::DriftBox::new(ctx.config.strategies.drift_box.clone(), ctx.config.fair_value.confidence_haircut),
    OpenMomentum   => open_momentum,   crate::strategy::open_momentum::OpenMomentumConfig,   true,  |ctx: &BuildCtx| crate::strategy::OpenMomentum::new(ctx.config.strategies.open_momentum.clone(), ctx.config.fair_value.confidence_haircut),
    ThetaCapture   => theta_capture,   crate::strategy::theta_capture::ThetaCaptureConfig,   true,  |ctx: &BuildCtx| crate::strategy::ThetaCapture::new(ctx.config.strategies.theta_capture.clone(), ctx.config.fair_value.confidence_haircut),
    PostCloseSweep => post_close_sweep,crate::strategy::post_close_sweep::PostCloseSweepConfig, true,  |ctx: &BuildCtx| crate::strategy::PostCloseSweep::new(ctx.config.strategies.post_close_sweep.clone()),
    RewardFarm     => reward_farm,     crate::strategy::reward_farm::RewardFarmConfig,     false, |ctx: &BuildCtx| crate::strategy::RewardFarm::new(ctx.config.strategies.reward_farm.clone(), ctx.registry.clone(), ctx.ledger.clone()),
    GRw1Maker      => g_rw1_maker,     crate::strategy::g_rw1_maker::GRw1MakerConfig, false, |ctx: &BuildCtx| crate::strategy::GRw1Maker::new(ctx.config.strategies.g_rw1_maker.clone()),
    ModelBtc5m     => model_btc5m,     crate::strategy::model_btc5m::ModelBtc5mConfig,     true,  |ctx: &BuildCtx| crate::strategy::ModelBtc5m::new(ctx.config.strategies.model_btc5m.clone(), ctx.model_prediction_tx.as_ref().expect("BuildCtx.model_prediction_tx required for ModelBtc5m -- the supervisor must inject the tool's Arc<sender>").subscribe(), ctx.config.mode),
    // The ctor is fail-closed: without `model_prediction_tx` it runs
    // degraded (p_missing=1, HOLD/SELL only) and without a `paper_approved`
    // artifact it stays disabled with a published reason. Do NOT use
    // `expect` here: the absence of the predictor channel must not abort
    // the spawn of the remaining strategies.
    Arb15m5m       => arb_15m5m,       crate::strategy::arb_15m5m::Arb15m5mConfig,         false, |ctx: &BuildCtx| crate::strategy::Arb15m5m::new(ctx.config.strategies.arb_15m5m.clone(), ctx.arb15m5m.clone()),
    RlPredictor    => rl_predictor,    crate::strategy::rl_predictor::RlPredictorConfig,   true,  |ctx: &BuildCtx| crate::strategy::RlPredictor::new(ctx.config.strategies.rl_predictor.clone(), ctx.model_prediction_tx.as_ref().map(|t| t.subscribe()), ctx.config.mode, ctx.config.as_ref()),
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::base_config_with_universe;
    use crate::types::Mode;

    /// Runs `spawn_all` with the given config and returns the names of the
    /// tasks it managed to spawn. Dummy channels: no strategy receives
    /// books, so the tasks just wait until `shutdown`.
    async fn spawned(cfg: Config) -> Vec<String> {
        use std::collections::HashMap;
        let (book_tx, _book_rx) = tokio::sync::broadcast::channel(16);
        let (intent_tx, _intent_rx) = tokio::sync::mpsc::channel(16);
        let (fill_tx, _fill_rx) = tokio::sync::broadcast::channel(16);
        let (_shutdown_tx, kill_rx) = tokio::sync::watch::channel(false);
        let risk = crate::risk::RiskGuard::new(crate::config::RiskConfig::default(), cfg.mode);
        // Registry tests: `ModelBtc5m` requires `model_prediction_tx` to be
        // built. Since here we test `spawn_all` (not the strategy itself),
        // the strategy is the one that fails if asked to spawn without a tx.
        // We leave the field as `None` and `register_strategies!` will
        // abort loudly if anyone tries to spawn `ModelBtc5m` in this test
        // context.
        let ctx = BuildCtx {
            config: Arc::new(cfg),
            registry: Arc::new(crate::market_feed::MarketRegistry::new()),
            ledger: crate::coordination::BracketLedger::new(),
            model_prediction_tx: None,
            arb15m5m: crate::strategy::Arb15m5mDeps::empty(),
        };
        let mut tasks = tokio::task::JoinSet::new();
        let mut task_names = HashMap::new();
        spawn_all(
            &ctx,
            &risk,
            &mut tasks,
            &mut task_names,
            &book_tx,
            &HashMap::new(),
            &intent_tx,
            &fill_tx,
            &kill_rx,
            5_000,
            &[],
        );
        tasks.shutdown().await;
        task_names.into_values().collect()
    }

    /// Test config with ARB as the only enabled strategy.
    fn cfg_arb_only(mode: Mode, paper_only: bool) -> Config {
        let mut cfg = base_config_with_universe(false);
        cfg.mode = mode;
        cfg.strategies.arb.limits.enabled = true;
        cfg.strategies.arb.limits.paper_only = paper_only;
        cfg
    }

    #[tokio::test]
    async fn in_live_enabled_strategy_is_spawned() {
        assert_eq!(
            spawned(cfg_arb_only(Mode::Live, false)).await,
            vec!["strategy:arb"]
        );
    }

    #[tokio::test]
    async fn in_paper_enabled_strategy_is_spawned() {
        assert_eq!(
            spawned(cfg_arb_only(Mode::Paper, false)).await,
            vec!["strategy:arb"]
        );
    }

    #[tokio::test]
    async fn paper_only_is_not_spawned_in_live() {
        assert!(
            spawned(cfg_arb_only(Mode::Live, true)).await.is_empty(),
            "paper_only must NOT spawn in live"
        );
    }

    /// The compiler does not protect `StrategyId::ALL` (unlike the
    /// exhaustive `match`es of `Display`/`FromStr`) -- a new variant
    /// forgotten there compiles cleanly and silently breaks the API
    /// listing, the universe validation at startup and, in the worst case,
    /// `StrategySupervisor::new`'s `boot_spawned`.
    #[test]
    fn registered_plus_follower_matches_strategy_id_all() {
        assert_eq!(
            REGISTERED.len() + 1,
            StrategyId::ALL.len(),
            "REGISTERED (register_strategies! table) + Follower must cover all of StrategyId::ALL"
        );
    }

    #[test]
    fn each_registered_is_in_strategy_id_all() {
        for id in REGISTERED {
            assert!(
                StrategyId::ALL.contains(id),
                "{id} is in REGISTERED but not in StrategyId::ALL"
            );
        }
    }

    #[test]
    fn follower_is_in_all_but_not_in_registered() {
        assert!(
            StrategyId::ALL.contains(&StrategyId::Follower),
            "Follower must be in StrategyId::ALL"
        );
        assert!(
            !REGISTERED.contains(&StrategyId::Follower),
            "Follower is deliberately left out of the table (hand-written config)"
        );
    }
}
